begin;
create table if not exists public.meeting_catalog (
 area_index integer primary key check(area_index between 0 and 125),
 points jsonb not null check(jsonb_typeof(points)='array'),
 updated_at timestamptz not null default now()
);
alter table public.meeting_catalog enable row level security;
drop policy if exists meeting_catalog_read on public.meeting_catalog;
create policy meeting_catalog_read on public.meeting_catalog for select to anon,authenticated using (true);
grant select on public.meeting_catalog to anon,authenticated;
on conflict (area_index) do update set points=excluded.points,updated_at=now();
commit;
select count(*) areas,sum(jsonb_array_length(points)) point_entries from public.meeting_catalog;
